use serde::Deserialize;
use serde_json::Value;

const CHUNK_SIZE: usize = 80;

#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct EquivalencyRulesOutputInput {
    pub official_rules: Vec<Value>,
    pub derived_rules: Vec<Value>,
}

pub fn render_equivalency_guide_typescript(
    input: &EquivalencyRulesOutputInput,
) -> Result<String, String> {
    let mut lines = vec![
        "/* eslint-disable */".to_string(),
        "/* auto-generated by automation/equivalency-refresh */".to_string(),
        String::new(),
        "import type { TransferPlannerEquivalencyRule } from \"./schema\";".to_string(),
        String::new(),
    ];

    write_rule_chunks(
        &mut lines,
        "TRANSFER_PLANNER_UW_GRC_EQUIVALENCY_GUIDE_RULE",
        &input.official_rules,
    )?;
    lines.extend([
        "export const TRANSFER_PLANNER_UW_GRC_EQUIVALENCY_GUIDE_RULES =".to_string(),
        "  TRANSFER_PLANNER_UW_GRC_EQUIVALENCY_GUIDE_RULES_RAW as TransferPlannerEquivalencyRule[];".to_string(),
        String::new(),
    ]);

    write_rule_chunks(
        &mut lines,
        "TRANSFER_PLANNER_UW_GRC_DERIVED_EQUIVALENCY_RULE",
        &input.derived_rules,
    )?;
    lines.extend([
        "export const TRANSFER_PLANNER_UW_GRC_DERIVED_EQUIVALENCY_RULES =".to_string(),
        "  TRANSFER_PLANNER_UW_GRC_DERIVED_EQUIVALENCY_RULES_RAW as TransferPlannerEquivalencyRule[];".to_string(),
        String::new(),
        "export const TRANSFER_PLANNER_UW_GRC_ALL_EQUIVALENCY_RULES =".to_string(),
        "  ([] as TransferPlannerEquivalencyRule[]).concat(".to_string(),
        "    TRANSFER_PLANNER_UW_GRC_EQUIVALENCY_GUIDE_RULES,".to_string(),
        "    TRANSFER_PLANNER_UW_GRC_DERIVED_EQUIVALENCY_RULES".to_string(),
        "  );".to_string(),
        String::new(),
    ]);

    Ok(format!("{}\n", lines.join("\n")))
}

fn write_rule_chunks(lines: &mut Vec<String>, prefix: &str, rules: &[Value]) -> Result<(), String> {
    let chunks: Vec<_> = rules.chunks(CHUNK_SIZE).collect();
    for (index, chunk) in chunks.iter().enumerate() {
        let chunk_json =
            serde_json::to_string_pretty(&Value::Array(chunk.to_vec())).map_err(|error| {
                format!("could not serialize generated equivalency rule chunk: {error}")
            })?;
        lines.push(format!(
            "const {prefix}_CHUNK_{index}: unknown[] = {chunk_json};"
        ));
        lines.push(String::new());
    }

    let chunk_names = chunks
        .iter()
        .enumerate()
        .map(|(index, _)| format!("  {prefix}_CHUNK_{index}"))
        .collect::<Vec<_>>()
        .join(",\n");
    lines.push(format!(
        "const {prefix}S_RAW: unknown[] = ([] as unknown[]).concat("
    ));
    lines.push(chunk_names);
    lines.push(");".to_string());
    lines.push(String::new());
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn renders_chunked_typescript_module_with_the_existing_exports() {
        let input = EquivalencyRulesOutputInput {
            official_rules: vec![json!({"id": "guide:1", "type": "direct-course"})],
            derived_rules: vec![json!({"id": "derived:1", "type": "sequence"})],
        };
        let output = render_equivalency_guide_typescript(&input).unwrap();
        assert!(output.contains("const TRANSFER_PLANNER_UW_GRC_EQUIVALENCY_GUIDE_RULE_CHUNK_0: unknown[] = [\n  {\n    \"id\": \"guide:1\",\n    \"type\": \"direct-course\"\n  }\n];"));
        assert!(output.contains(
            "const TRANSFER_PLANNER_UW_GRC_DERIVED_EQUIVALENCY_RULE_CHUNK_0: unknown[] = ["
        ));
        assert!(output.contains("TRANSFER_PLANNER_UW_GRC_ALL_EQUIVALENCY_RULES"));
        assert!(output.ends_with("\n"));
    }

    #[test]
    fn starts_a_new_chunk_at_the_existing_eighty_rule_boundary() {
        let input = EquivalencyRulesOutputInput {
            official_rules: (0..81)
                .map(|index| json!({"id": format!("rule:{index}")}))
                .collect(),
            derived_rules: Vec::new(),
        };
        let output = render_equivalency_guide_typescript(&input).unwrap();
        assert!(output.contains("TRANSFER_PLANNER_UW_GRC_EQUIVALENCY_GUIDE_RULE_CHUNK_0"));
        assert!(output.contains("TRANSFER_PLANNER_UW_GRC_EQUIVALENCY_GUIDE_RULE_CHUNK_1"));
    }
}
